export const STADIUM_LOCATIONS: Location[] = stadiumRows.map(
  ([name, country, lat, lng, category, difficulty, hint], i) => ({
    id: `wikidata-stadium-${i}`,
    name,
    country,
    lat,
    lng,
    category,
    difficulty,
    hint,
  }),
);

export const WONDER_AND_ATTRACTION_LOCATIONS: Location[] = wonderAttractionRows.map(
  ([name, country, lat, lng, category, difficulty, hint], i) => ({
    id: `wikidata-wonder-${i}`,
    name,
    country,
    lat,
    lng,
    category,
    difficulty,
    hint,
  }),
);

export function getStadiumLocations(): Location[] {
  return STADIUM_LOCATIONS;
}

export function getWonderAndAttractionLocations(): Location[] {
  return WONDER_AND_ATTRACTION_LOCATIONS;
}
